// Turns the agent's Markdown into an Obsidian note and an email body.
const cfg = $('Config').first().json;
const answer = String($input.first().json.output ?? '').trim();
if (!answer) throw new Error('The AI Agent returned no output');

const heading = answer.match(/^#\s+(.+)$/m);
const title = heading ? heading[1].trim() : 'Feed research';
// Characters Obsidian refuses (or treats as link syntax) in file names.
const safeTitle = title.replace(/[\\/:*?"<>|#^\[\]]/g, '').replace(/\s+/g, ' ').trim().slice(0, 80) || 'Feed research';
const stamp = $now.toFormat('yyyy-MM-dd HHmm');
const notePath = `${cfg.obsidianFolder}/${stamp} ${safeTitle}.md`;

const quotedPrompt = String(cfg.prompt).split('\n').map((line) => '> ' + line).join('\n');
const content = [
  '---',
  `created: ${$now.toISO()}`,
  'source: feed-reader',
  'tags: [research, feed-reader]',
  '---',
  '',
  answer,
  '',
  '> [!info]- Prompt',
  quotedPrompt,
  '',
].join('\n');

const obsidianLink = `obsidian://open?vault=${encodeURIComponent(cfg.obsidianVault)}&file=${encodeURIComponent(notePath)}`;
const emailMarkdown = `${answer}\n\n---\n\nSaved to Obsidian: [${cfg.obsidianVault}/${notePath}](${obsidianLink})\n`;

return [{
  json: {
    title,
    notePath,
    // The Local REST API takes the vault-relative path in the URL, one encoded segment at a time.
    noteUrl: `${cfg.obsidianApiUrl.replace(/\/+$/, '')}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`,
    content,
    emailMarkdown,
    emailTo: cfg.emailTo,
  },
}];
